export type PageView = {
  path: string
  timestamp: string
}

/**
 * Records a page view with the analytics service.
 * Intended to be scheduled with `after()` so it does not block the response.
 */
export async function logPageView(path: string): Promise<void> {
  const event: PageView = {
    path,
    timestamp: new Date().toISOString(),
  }

  const endpoint = process.env.ANALYTICS_ENDPOINT
  if (!endpoint) {
    console.info('[analytics] page_view', event)
    return
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ event: 'page_view', ...event }),
  })

  if (!response.ok) {
    throw new Error(`Analytics service responded with ${response.status}`)
  }
}

