import { after, connection } from 'next/server'
import { logPageView } from '@/app/analytics'

export default async function Home() {
  // Page views must run per request. `after` alone does not opt the route into dynamic rendering.
  await connection()

  // Runs after the response is finished, so analytics does not block the page.
  after(() => {
    return logPageView('/')
  })

  return (
    <main>
      <h1>Welcome</h1>
    </main>
  )
}

